#include <string>
#include <algorithm>

using namespace std;

class Solution {
public:
    int minOperations(string s) {
        if (is_sorted(s.begin(), s.end())) {
            return 0;
        }
        int n = s.length();
        if (n <= 2) {
            return -1;
        }

        char min_ch = *min_element(s.begin(), s.end());
        char max_ch = *max_element(s.begin(), s.end());

        if (s.front() == min_ch || s.back() == max_ch) {
            return 1;
        }

        if (s.front() == max_ch && s.back() == min_ch) {
            int count_min = count(s.begin(), s.end(), min_ch);
            int count_max = count(s.begin(), s.end(), max_ch);
            if (count_min == 1 && count_max == 1) {
                return 3;
            }
        }

        return 2;
    }
};
